// Renfe's marks as its trains carry them, drawn from Renfe's own artwork
// (Wikimedia Commons, public-domain text logos: "Logotipo - Renfe
// Operadora.svg" for the wordmark, "Renfe AVE.svg" for AVE's), never set in
// a font. Each is placed in a car's feet frame (y up) and reads left to right
// on a car drawn mirrored too, as the lettering on both sides of a train does.
export const RENFE_PURPLE = "#851765", AVE_GREY = "#98989a";
const r3 = (v) => Math.round(v * 1000) / 1000;
// Paths in one fill (kept apart: the artwork's paths start with relative moves).
const paths = (fill, ds) => ds.map((d) => `<path fill="${fill}" d="${d}"/>`).join("");
// Artwork drawn k ft per unit, the point (ax, ay) of its box at (x, y).
const place = (c, x, y, k, ax, ay, body) =>
  `<g transform="translate(${r3(x)} ${r3(y)}) scale(${r3((c.mirrored ? -1 : 1) * k)} ${r3(-k)}) translate(${-ax} ${-ay})">${body}</g>`;

