  place(c, x, y, h / 100, 149.5, 78, (renfe ? paths(renfe, AVLO_R) : "") + paths(word, AVLO_W) + paths(smile, AVLO_S));

// The big V Renfe paints on the AVE power cars' inner ends (Series 102/112
// and 106): the falling stroke grey, the rising one aubergine, meeting in a
// point at the foot; h ft tall, centered on (x, y).
export const aveV = (c, x, y, h, { grey = AVE_GREY, purple = RENFE_PURPLE } = {}) =>
  place(c, x, y, h / 100, 0, 50, `<path fill="${grey}" d="M-31 0L-16 0L2 88L0 100Z"/><path fill="${purple}" d="M17 0L33 0L0 100L-3 89Z"/>`);

