export const LOCKUP_GREY = "#60646c";
export const lockup = (c, kind, x, y, h, { purple = RENFE_PURPLE, grey = LOCKUP_GREY, red = "#ef2c30", white = "#ffffff" } = {}) => {
  const [w, H, body] = LOCKUPS[kind];
  return place(c, x, y, h / H, w / 2, H / 2, body(purple, grey, red, white));
};
// Cercanías' mark, the "galleta" ("Cercanias Logo.svg"): a red disc with a
// white ring open at the lower left; r ft its radius.
export const cercaniasMark = (c, x, y, r, { red = "#ef2c30", white = "#ffffff" } = {}) =>
  place(c, x, y, r / 150, 150, 150, `<circle cx="150" cy="150" r="150" fill="${red}"/><path fill="${white}" d="M150 100C177.4 100 200 122.6 200 150C200 177.4 177.4 200 150 200C122.6 200 100 177.4 100 150L50 150C50 204.9 95.1 250 150 250C204.9 250 250 204.9 250 150C250 95.1 204.9 50 150 50Z"/>`);

