export const rodaliesLockup = (c, x, y, h, { ink = "#2f3a4f", orange = "#f47216" } = {}) => {
  const bw = h * 0.5, k = (h * 0.34) / 714, m = c.mirrored ? -1 : 1;
  // Built from the box's left edge; on a mirrored car the group is turned back.
  const body = `<rect x="0" y="${r3(-h / 2)}" width="${r3(bw)}" height="${r3(h)}" fill="${orange}"/>` +
    `<g transform="translate(${r3(bw * 0.56)} ${r3(h * 0.2)}) scale(${(h * 0.4 / 77.633).toPrecision(4)}) translate(-36.64 -38.82)"><path fill="#ffffff" d="${RDC_R}"/></g>` +
    `<g transform="translate(${r3(bw + h * 0.1)} ${r3(h * 0.06)}) scale(${(k).toPrecision(4)})"><path fill="${ink}" d="${RDC_WORD}"/></g>` +
    `<g transform="translate(${r3(bw + h * 0.1)} ${r3(-h * 0.26)}) scale(${(k * 0.68).toPrecision(4)})"><path fill="${ink}" d="${RDC_SUB}"/></g>`;
  return `<g transform="translate(${r3(x - m * bw / 2)} ${r3(y)}) scale(${m} 1)">${body}</g>`;
};
